#!/usr/bin/env python3
"""Archive one explicit completed isolation run. CPU/file operations only."""
import argparse, datetime, gzip, hashlib, json, pathlib, shutil
p=argparse.ArgumentParser();p.add_argument('label');a=p.parse_args()
root=pathlib.Path.cwd();base=root/'benchmarks-local/isolation-2026-10-16';label=a.label
assert label in {'observed-ui-hour','observed-none-hour','observed-audio-hour'}
src=base/label;result=json.loads((src/'result.json').read_text());launch=json.loads((base/f'{label}-launch.json').read_text())
assert result['status']=='ok' and launch['returncode']==0, 'Only completed successful runs may be staged'
out=base/'staged-archive'/label
assert not out.exists(), f'Refusing to overwrite {out}'
out.mkdir(parents=True)
files={}
def digest(b):return hashlib.sha256(b).hexdigest()
def add(source,target=None,expected=None,compress=False):
    source=pathlib.Path(source);target=target or source.name
    raw=source.read_bytes()
    if expected:assert digest(raw)==expected,(source,'source pin mismatch')
    dest=out/target
    if compress:
        with dest.open('wb') as f:
            with gzip.GzipFile(filename='',mode='wb',fileobj=f,mtime=0,compresslevel=6) as g:g.write(raw)
        assert gzip.decompress(dest.read_bytes())==raw
    else:shutil.copyfile(source,dest)
    data=dest.read_bytes();entry={'source':str(source.relative_to(root)),'bytes':len(data),'sha256':digest(data)}
    if compress:entry.update(decompressed_bytes=len(raw),decompressed_sha256=digest(raw),gzip_mtime=0,gzip_filename='',exact_raw_verification=True)
    files[target]=entry
for name in ['result.json','progress.json']:add(src/name)
mode=result['load_mode'];selected=result['selected_loads']
assert set(selected)=={'ui':{'ui'},'none':set(),'audio':{'audio'}}[mode]
for load in ('ui','audio'):
    if load in selected:
        for name in (f'{load}.json',f'{load}.stderr'):add(src/name)
        if load=='ui':add(src/'ui-progress.json')
    else:
        assert not (src/f'{load}.json').exists() and not (src/f'{load}.stderr').exists(), 'Disabled probe unexpectedly present'
for name in ['events.jsonl','native-trace.jsonl']:add(src/name,name+'.gz',compress=True)
external={'before.json':f'before-{label}.json','after.json':f'after-{label}.json','launcher.stdout':f'{label}.stdout','launcher.stderr':f'{label}.stderr','admission.json':f'{label}-admission.json','cleanup-host.json':f'{label}-cleanup.json','cooldown.json':f'{label}-cooldown.json','cooldown.jsonl':f'{label}-cooldown.jsonl','guard.json':f'{label}-guard.json','kernel-compact.json':f'{label}-kernel.json','launch.json':f'{label}-launch.json','normal-ready.json':f'{label}-normal-ready.json','normal-ready.jsonl':f'{label}-normal-ready.jsonl','policy-lifecycle.json':f'{label}-policy.json','thermal.json':f'{label}-thermal.json','verification.json':f'{label}-verification.json'}
if 'ui' in selected:external['guard.js']=f'{label}-guard.js'
for target,name in external.items():add(base/name,target)
pins=result['pins']
for key,name in {'soak_source':'stem_soak-executed-v3.py','shared_benchmark_source':'stem_worker-executed.py','worker_source':'worker-executed.py','sampler_source':'worker_support-executed.py'}.items():
    pin=pins[key];add(pathlib.Path(pin['path']),name,expected=pin['sha256'])
assert pins['soak_source']['sha256']=='52605983fdd2416caf63477bc9314096a0daa4f251e798c92928be19e5fea8b8'
for name,sha in launch['wrapper_pins'].items():add(base/name,'producer-'+name,expected=sha)
add(root/'tools/benchmarks/window_guard.py','window_guard-executed.py',expected='077bd16eefbdd9b80f787b6aeb2837a3790fedf7f5defd7b140dccc6e1f5cebb')
provenance={'schema':1,'scope':'Explicit completed run only; saved file reads, deterministic gzip and hash verification; no host commands, GPU, build, test, or active worker-only trace reads.','run':label,'load_mode':mode,'selected_loads':selected,'disabled_loads':{load:{'artifact_present':False,'observation':'not_run; no report or stderr fabricated'} for load in ('ui','audio') if load not in selected},'repository_head_from_result':result['repository_head'],'soak_code_commit':'b375522216d2d81a9d1d011017fb25474be0dacf','producer_snapshot_note':'Producer sources were copied only when current bytes exactly matched their launch/result pins. Their original workspace paths remain unchanged in saved evidence; copy sources back to that layout before reproducing the orchestration.','excluded':'No runtime/UI/audio binaries, model, WAV/F32 audio, stop marker, full-local kernel journal or independently derived audits.','raw_manifest_scope':'All files created by this archive helper except raw-manifest.json itself. Later independent audits need their own manifest and eventual top-level manifest.'}
(out/'source-provenance.json').write_text(json.dumps(provenance,indent=2)+'\n')
b=(out/'source-provenance.json').read_bytes();files['source-provenance.json']={'source':'generated by stage_completed_raw.py from saved result/launch metadata','bytes':len(b),'sha256':digest(b)}
manifest={'schema':1,'scope':provenance['raw_manifest_scope'],'archived_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'files':files,'executed_source_pins_from_result':pins,'repository_head':result['repository_head'],'archive_helper_sha256':digest(pathlib.Path(__file__).read_bytes())}
(out/'raw-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
for name,entry in files.items():
    b=(out/name).read_bytes();assert len(b)==entry['bytes'] and digest(b)==entry['sha256']
    if name.endswith('.gz'):
        r=gzip.decompress(b);assert len(r)==entry['decompressed_bytes'] and digest(r)==entry['decompressed_sha256']
print(json.dumps({'label':label,'path':str(out),'raw_owned_files':len(files),'stored_bytes':sum(x['bytes'] for x in files.values()),'manifest_sha256':digest((out/'raw-manifest.json').read_bytes()),'all_file_and_gzip_checks_passed':True,'disabled_loads':provenance['disabled_loads']},indent=2))
